package com.ruoyi.hexu;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

/** Closed calendar periods produce durable evidence, then a separate reviewed rank change. */
public final class HexuDowngrades {
 private final HexuStore db;
 public HexuDowngrades(HexuStore db){this.db=db;}
 private static LocalDate parse(String value){try{return LocalDate.parse(value);}catch(Exception e){throw new BusinessException("请填写有效的首次考核开始日期");}}
 public static void validate(Map<String,Object>b){if(!bool(b,"enabled"))return;HexuAssessment.validate(b);require(number(b,"rank")==2||number(b,"rank")==3,"降级方案适用职级须为分货中心或总代理");require(Arrays.asList("QUARTER","YEAR").contains(str(b,"periodKind")),"降级考核须为自然季度或自然年度");require(number(b,"failurePeriods")>=1&&number(b,"failurePeriods")<=8,"连续不达标次数须为1至8");LocalDate first=parse(str(b,"firstPeriodStart"));require(first.getDayOfMonth()==1&&("YEAR".equals(str(b,"periodKind"))?first.getMonthValue()==1:(first.getMonthValue()-1)%3==0),"首次考核须从季度或年度第一天开始");require(first.getYear()>=2000&&first.getYear()<=LocalDate.now(ZoneOffset.UTC).getYear()+5,"考核开始年份无效");}
 public int run(long shop,LocalDate today){int count=0;Set<Long>ranks=new HashSet<>();for(Map<String,Object>rule:db.jdbc().queryForList("select * from hx_document where shop_id=? and kind='downgrade_rule' and status='ACTIVE' order by updated_at desc,id desc",shop)){Map<String,Object>c=db.parse(rule.get("body_json"));long rank=number(c,"rank");if(!ranks.add(rank)||!bool(c,"enabled"))continue;validate(c);LocalDate first=parse(str(c,"firstPeriodStart"));int months="YEAR".equals(str(c,"periodKind"))?12:3;
 for(Map<String,Object>a:db.jdbc().queryForList("select * from hx_agent where shop_id=? and rank_no=? and status='ACTIVE' order by id",shop,rank)){db.one("select id from hx_agent where id=? for update",a.get("id"));LocalDate joined=((Timestamp)a.get("approved_at")).toLocalDateTime().toLocalDate(),aligned=months==12?joined.withDayOfYear(1):LocalDate.of(joined.getYear(),((joined.getMonthValue()-1)/3)*3+1,1);if(joined.isAfter(aligned))aligned=aligned.plusMonths(months);LocalDate assessmentStart=first.isAfter(aligned)?first:aligned;long failures=0;int examined=0;for(LocalDate from=assessmentStart;!from.plusMonths(months).isAfter(today);from=from.plusMonths(months)){LocalDate until=from.plusMonths(months);Map<String,Object>old=db.optional("select * from hx_assessment_period where rule_id=? and agent_id=? and period_start=?",rule.get("id"),a.get("id"),from.toString());if(old!=null){failures=number(old,"failures");continue;}if(examined++>=40)break;Map<String,Object>evaluation=new HexuAssessment(db).evaluateWindow(number(a,"member_id"),shop,c,from,until);boolean passed=bool(evaluation,"qualified");failures=passed?0:failures+1;String record=id("KH");db.jdbc().update("insert into hx_assessment_period(id,rule_id,shop_id,agent_id,member_id,rank_no,period_start,period_end,passed,failures,evaluation_json) values(?,?,?,?,?,?,?,?,?,?,?)",record,rule.get("id"),shop,a.get("id"),a.get("member_id"),rank,from.toString(),until.toString(),passed,failures,db.json(evaluation));count++;
 if(failures>=number(c,"failurePeriods")&&db.jdbc().queryForObject("select count(*) from hx_document where shop_id=? and member_id=? and kind='downgrade' and status in ('PENDING','SCHEDULED')",Long.class,shop,a.get("member_id"))==0){String doc=id("DG");Map<String,Object>b=map("name","连续"+failures+"个"+(months==12?"年度":"季度")+"未达标","agentId",a.get("id"),"fromRank",rank,"rank",rank-1,"ruleId",rule.get("id"),"periodId",record,"periodStart",from.toString(),"periodEnd",until.toString(),"failures",failures,"requiredFailures",c.get("failurePeriods"),"config",c,"assessment",evaluation);db.jdbc().update("insert into hx_document(id,shop_id,member_id,kind,status,body_json) values(?,?,?,'downgrade','PENDING',?)",doc,shop,a.get("member_id"),db.json(b));db.audit(new Actor(0,true,true),shop,"DOWNGRADE_PROPOSE",doc,null,b);db.message(shop,number(a,"member_id"),"考核未达标，降级申请待审核",doc);}
 }
 }}return count;}
 public Map<String,Object> reviewEvidence(long member,long shop,Map<String,Object>b){Map<String,Object>agent=db.agent(member,shop);require(agent!=null&&number(agent,"rank_no")==number(b,"fromRank"),"代理当前职级已变化，请重新评估");Map<String,Object>c=(Map<String,Object>)b.get("config");require(c!=null&&number(b,"requiredFailures")>0,"缺少原考核快照");LocalDate end=parse(str(b,"periodEnd"));int months="YEAR".equals(str(c,"periodKind"))?12:3;List<Map<String,Object>>periods=new ArrayList<>();for(int i=0;i<number(b,"requiredFailures");i++){LocalDate start=end.minusMonths(months);Map<String,Object>e=new HexuAssessment(db).evaluateWindow(member,shop,c,start,end);require(!bool(e,"qualified"),"复核发现考核周期已达标，不满足连续降级条件");periods.add(e);end=start;}return map("periods",periods,"checkedAt",System.currentTimeMillis());}
 public void apply(long member,long shop,Map<String,Object>b){db.one("select id from hx_shop where id=? for update",shop);Map<String,Object>a=db.one("select * from hx_agent where member_id=? and shop_id=? and status='ACTIVE' for update",member,shop);long rank=number(b,"rank");require(number(a,"rank_no")==number(b,"fromRank")&&rank==number(b,"fromRank")-1&&rank>=1,"降级仅允许逐级生效，当前职级已变化");require(rank>=2||db.jdbc().queryForObject("select count(*) from hx_shop where owner_id=? and status in ('ACTIVE','ONBOARDING','CLOSING')",Long.class,member)==0,"经营中的商城必须先完成转让、合并或停业，才能降为云代理");require(db.jdbc().queryForObject("select count(*) from hx_agent where parent_id=? and status='ACTIVE' and rank_no>?",Long.class,a.get("id"),rank)==0,"存在高于新职级的下级，请先审核调整团队关系");
 for(Map<String,Object>d:db.jdbc().queryForList("select body_json from hx_document where kind='peer_authorization' and status='ACTIVE'")){Map<String,Object>peer=db.parse(d.get("body_json"));require(number(peer,"parentAgentId")!=number(a,"id")&&number(peer,"childAgentId")!=number(a,"id"),"存在跨商城同级分红授权，请先审核处置关系");}
 db.jdbc().update("update hx_agent set rank_no=? where id=?",rank,a.get("id"));db.audit(new Actor(0,true,true),shop,"DOWNGRADE_EFFECTIVE",str(b,"periodId"),map("agentId",a.get("id"),"rank",b.get("fromRank")),map("rank",rank,"effectiveAt",b.get("effectiveAt")));db.message(shop,member,"职级降级已生效，新订单使用新价格",str(b,"periodId"));}
}
